// Merges the real registry snapshot (school names, counts, real spell stats)
// with Arcane Vellum presentation metadata (rune glyph, flavor, family).
// Snapshot is generated by scripts/gen-registry-snapshot.mjs from the live game registry.
import snapshot from './registry-snapshot.json';

export function slugify(name = '') {
  return String(name)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/([a-z])([A-Z])/g, '$1-$2')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// Rune + flavor + family per school (presentation only, from the Lobby mock).
