  Lightning:   { rune: 'ᛏ', family: 'Primal', flavor: '"Entre o trovão e o raio, há tempo para um pedido — mas só um."' },
  Nature:      { rune: 'ᛗ', family: 'Primal', flavor: '"Raízes lembram. Galhos esquecem. Folhas perdoam."' },
  Elemental:   { rune: 'ᛒ', family: 'Primal', flavor: '"O panteão dos guias atende a quem oferece tambor e fé."' },
