  Celestial:   { rune: 'ᚨ', family: 'Arcane', flavor: '"As estrelas estão muito longe — exatamente onde queremos que estejam."' },
  Echolith:    { rune: 'ᛚ', family: 'Arcane', flavor: '"Cada eco é uma versão menor do som original. Aprenda a empilhá-los."' },
  Tensorveil:  { rune: 'ᛞ', family: 'Arcane', flavor: '"O véu é tecido. O tecido pode ser puxado. O puxão fere quem o puxa."' },
  Aetherforge: { rune: 'ᚷ', family: 'Arcane', flavor: '"Forje o impossível em três golpes: alpha, beta, gamma."' },
  Prismatica:  { rune: 'ᛇ', family: 'Arcane', flavor: '"A luz branca é uma mentira gentil. Quebre-a, e verás as sete verdades que ela escondia."' },
  Void:        { rune: 'ᛟ', family: 'Veil', flavor: '"O vazio não morde. Ele apenas espera."' },
  Lust:        { rune: 'ᛒ', family: 'Veil', flavor: '"O desejo é um feitiço que se conjura sem palavra."' },
  PureCinema:  { rune: 'ᚱ', family: 'Veil', flavor: '"Corte. Bullet time. Director\'s cut. Tudo é encenação até o impacto."' },
