const FAMILY_ORDER = ['Primal', 'Arcane', 'Veil', 'Spirit'];

// Schools keyed by registry index (same order the game's setSchool expects).
export const SCHOOLS = snapshot.schools.map((s, index) => {
  const meta = META[s.name] || { rune: '◆', family: 'Arcane', flavor: '' };
  return {
    index,
    name: s.name,
    slug: slugify(s.name),
    colorVar: `var(--school-${slugify(s.name)})`,
    rune: meta.rune,
    family: meta.family,
    flavor: meta.flavor,
    count: s.count,
    spells: s.spells,
  };
});

// Grouped for the roster grid.
export const FAMILIES = FAMILY_ORDER.map((label) => ({
  label,
  schools: SCHOOLS.filter((s) => s.family === label),
})).filter((f) => f.schools.length > 0);

export const TOTAL_SCHOOLS = SCHOOLS.length;

export function formatCd(ms) {
  if (ms == null) return '—';
  return `${(ms / 1000).toFixed(ms % 1000 === 0 ? 0 : 1)}s`;
}
